insert into public.reading_open_questions (reading_text_id, question_en, sort_order)
select rt.id, gen.question_en, gen.sort_order
from public.reading_texts rt
join (values
  ('The Night Market', 'Describe how the writer got lost and how the problem was solved, in your own words.', 1),
  ('The Night Market', 'Have you ever been lost somewhere unfamiliar? What happened, and what did you learn from it?', 2),
  ('Learning to Cook at Thirty', 'What mistakes did the writer make at the beginning, and what did each one teach them?', 1),
  ('Learning to Cook at Thirty', 'Is there a skill you learned as an adult? How did you learn it, and what was the hardest part?', 2),
  ('Why Songs Get Stuck in Our Heads', 'Summarise the three common features of earworms described in the text.', 1),
  ('Why Songs Get Stuck in Our Heads', 'Which song gets stuck in your head most often? Why do you think that song in particular?', 2),
  ('A Shorter Week?', 'Explain one argument for and one argument against the four-day week, using the text.', 1),
  ('A Shorter Week?', 'Would a four-day week work in a job or school you know well? Why or why not?', 2),
  ('The Hidden Cost of Convenience', 'Identify the three costs of convenience the writer describes and explain who pays each one.', 1),
  ('The Hidden Cost of Convenience', 'Do you agree that ''convenience is never free''? Support your view with an example from your own life.', 2),
  ('What Libraries Are For Now', 'According to the text, who uses libraries today and for what purposes?', 1),
  ('What Libraries Are For Now', 'Should libraries take on roles like teaching digital skills, or should other services do this? Explain your view.', 2),
  ('On Being Wrong', 'Explain in your own words the difference between certainty and ''structured doubt'' as the writer describes them.', 1),
  ('On Being Wrong', 'Describe a time you changed your mind about something important. What made you change it, and how did it feel?', 2),
  ('The Map Is Not the Territory', 'Explain the hospital example and what it shows about the relationship between measurements and reality.', 1),
  ('The Map Is Not the Territory', 'Think of a ''map'' you rely on in your own life (a grade, a schedule, a rating). In what ways might it differ from the ''territory'' it describes?', 2)
) as gen(title_en, question_en, sort_order)
  on rt.title_en = gen.title_en;

insert into public.listening_clips (title_he, title_en, transcript_en, cefr_level, style, sort_order) values
  ('הודעה קולית מבעל הדירה', 'A Voice Message from the Landlord', 'Hi, it''s Michael, your landlord. I''m calling about the kitchen tap you told me about last week. I''ve found a plumber who can come on Thursday morning, between nine and eleven. If that time doesn''t work for you, just let me know and I''ll ask him for another day. He''ll need to turn off the water for about an hour, so you might want to fill a few bottles before he arrives. Oh, and one more thing. The building''s front door code is changing on the first of next month. I''ll send you the new code by text message a few days before. Thanks, and sorry it took so long to sort this out. Bye.', 'B1', 'standard', 100),
  ('קביעת תור לרופאה', 'Booking a Doctor''s Appointment', 'Good morning, Green Street Clinic. How can I help? Hi, I''d like to make an appointment with Doctor Levi, please. Of course. Is it urgent? Not really. I''ve had a sore throat for about a week and it''s not getting better. I see. Doctor Levi''s first free appointment is on Monday at four fifteen. Is there anything earlier? I could do Friday morning with Doctor Cohen instead, at ten thirty. Friday is better, thanks. Fine. Can I have your ID number? Sure, it''s on my card, one moment. And please arrive ten minutes early, because we need to update your details. No problem. Thank you.', 'B1', 'standard', 101),
  ('החזרת מחשב נייד תקול', 'Returning a Faulty Laptop', 'Thanks for holding. You''re through to customer support, this is Noa. Hi. I bought a laptop from your website about three weeks ago, and the screen has started flickering. It happens every few minutes, and sometimes it goes completely black. I''m sorry to hear that. Have you tried updating the graphics driver? Yes, I did that on the first day it happened, and it made no difference. Okay. Since you''re still within the thirty-day return period, you have two options. We can send you a prepaid label to return it for a full refund, or we can arrange a replacement, which would arrive in about five working days. I''d prefer a replacement, but I need a computer for work. Can the new one be sent before I return this one? Normally we wait for the return, but I can make an exception in this case. I''ll send the replacement today and give you two weeks to send the faulty one back. That would be really helpful. Thank you.', 'B2', 'standard', 102),
  ('פתיחת פודקאסט: מסכים ושינה', 'A Podcast Opening: Screens and Sleep', 'Welcome back to the show. Today we''re talking about something that most of us do every night without thinking: looking at a screen just before going to sleep. Maybe it''s one more episode, one more scroll through the news, or answering that message that could definitely have waited until morning. Many listeners wrote to us saying they feel tired even after a full night in bed, and several of them mentioned their phone habits. So in this episode, we''re not going to tell you to throw your phone away, because let''s be honest, that''s not going to happen. Instead, we''ll look at small changes that some people find helpful, like keeping the phone outside the bedroom, or choosing a fixed time each evening to stop checking work email. Later on, a listener named Tamar will share what happened when she tried a screen-free hour before bed for a month.', 'B2', 'standard', 103),
  ('ישיבת צוות על עיכוב', 'A Team Meeting About a Delay', 'Okay, let''s start. I''ll be direct: we''re not going to make the launch date of the fifteenth. The payment integration took longer than we estimated, and the testing we''ve done so far has turned up more issues than we''d like. Now, we have two realistic options. Option one is to launch on time with payments switched off, and add them in a second release two weeks later. Option two is to move the whole launch back by about ten days. My concern with option one is that customers will try to pay, hit a wall and simply leave, and first impressions are hard to undo. On the other hand, marketing has already booked the campaign for the fifteenth, and changing that will cost us. So before we decide, I''d like each of you to tell me honestly how confident you are in a ten-day estimate, because if it turns into three weeks, we''ll have the worst of both options.', 'C1', 'standard', 104),
  ('מדריך קולי במוזיאון', 'A Museum Audio Guide', 'You''re now standing in front of one of the most frequently copied paintings in this collection, and yet, as you''ll notice, it''s surprisingly small. Visitors often expect something grand, and they''re a little disappointed at first. Take a moment, though, to look at the light coming through the window on the left. The painter applied the paint in extremely thin layers, which is why the light seems to sit on the surface of the wall rather than simply being painted onto it. Now look at the woman''s hands. They''re not quite finished, and art historians have argued for years about whether that was a deliberate choice or whether the painter simply ran out of time. There''s no record that settles the question. What we do know is that the painting changed hands at least four times before it arrived here, and on one occasion it was sold for less than the price of its frame.', 'C1', 'standard', 105),
  ('מסה ברדיו על שקט', 'A Radio Essay on Silence', 'I''ve been thinking lately about how rarely we encounter genuine silence, and how uneasy it makes us when we do. In a conversation, a pause of more than a few seconds tends to be filled almost immediately, often with something nobody particularly needed to say. On a train, the quiet carriage is quiet only in the narrowest sense; everyone is listening to something through headphones. It''s as if silence has come to be understood as an absence, a gap waiting to be filled, rather than as something with a character of its own. Yet anyone who has spent time somewhere truly quiet, a desert at night, say, or an empty church, knows that silence isn''t empty at all. It has texture. It makes small sounds audible that were always there, and, rather more unsettlingly, it makes our own thoughts audible too. Perhaps that''s the real reason we avoid it.', 'C2', 'standard', 106),
  ('דיון על למידה מקוונת', 'A Debate on Learning Online', 'Let me push back on that a little. You''re right that online courses have made an enormous amount of material available, and that''s genuinely valuable. But access to material was never really the bottleneck. University libraries have offered more than any student could read for centuries. What students lacked, and still lack, is the structure that turns material into learning: deadlines, feedback from someone who knows the subject, and peers who notice when you stop showing up. Online courses can provide some of that, of course, but the ones that do are expensive to run, which rather undermines the promise of free education for everyone. So I''d frame the question differently. It isn''t whether learning online works. It clearly can. It''s whether we''re willing to fund the human parts of it, or whether we''re going to keep confusing a library with a teacher.', 'C2', 'standard', 107);

insert into public.exercises (type, skill_area, listening_clip_id, cefr_level, content, sort_order)
select 'mcq'::exercise_type, 'listening'::skill_area, lc.id, lc.cefr_level, gen.content::jsonb, gen.sort_order
from public.listening_clips lc
join (values
  ('A Voice Message from the Landlord', '{"prompt":"Why is the landlord calling?","options":["To ask about the rent","To arrange a repair of the kitchen tap","To complain about noise","To invite the tenant to a meeting"],"correctIndex":1}', 2),
  ('A Voice Message from the Landlord', '{"prompt":"When can the plumber come?","options":["The first of next month","Thursday afternoon","Thursday morning, between nine and eleven","Next Monday"],"correctIndex":2}', 3),
  ('A Voice Message from the Landlord', '{"prompt":"What does the landlord suggest the tenant do before the plumber arrives?","options":["Buy a new tap","Leave the door open","Clean the kitchen","Fill a few bottles with water"],"correctIndex":3}', 4),
  ('Booking a Doctor''s Appointment', '{"prompt":"Why does the caller want to see a doctor?","options":["A headache","A sore throat that is not getting better","A broken arm","A check-up before travelling"],"correctIndex":1}', 2),
  ('Booking a Doctor''s Appointment', '{"prompt":"Which appointment does the caller choose?","options":["Monday at ten thirty with Doctor Cohen","Monday at four fifteen with Doctor Levi","Friday at ten thirty with Doctor Cohen","Friday at four fifteen with Doctor Levi"],"correctIndex":2}', 3),
  ('Booking a Doctor''s Appointment', '{"prompt":"Why should the caller arrive early?","options":["To pay in advance","To have a blood test","The doctor is often late","To update their details"],"correctIndex":3}', 4),
  ('Returning a Faulty Laptop', '{"prompt":"What is wrong with the laptop?","options":["It does not turn on","The screen flickers and sometimes goes black","The keyboard stopped working","The battery runs out quickly"],"correctIndex":1}', 2),
  ('Returning a Faulty Laptop', '{"prompt":"What two options does the agent offer?","options":["A gift card or a refund","A repair or a discount","A full refund or a replacement","A new driver or a repair"],"correctIndex":2}', 3),
  ('Returning a Faulty Laptop', '{"prompt":"What exception does the agent make?","options":["She offers free delivery","She extends the warranty to two years","She gives a refund after thirty days","She sends the replacement before the faulty laptop is returned"],"correctIndex":3}', 4),
  ('A Podcast Opening: Screens and Sleep', '{"prompt":"What is the topic of today''s episode?","options":["Choosing a new phone","Looking at screens before sleep","Working from home","Reading the news"],"correctIndex":1}', 2),
  ('A Podcast Opening: Screens and Sleep', '{"prompt":"What did many listeners report?","options":["They work at night","They sleep too much","They feel tired even after a full night in bed","They don''t own phones"],"correctIndex":2}', 3),
  ('A Podcast Opening: Screens and Sleep', '{"prompt":"What will Tamar talk about later?","options":["Throwing her phone away","A new sleep app she designed","Her job as a doctor","A month with a screen-free hour before bed"],"correctIndex":3}', 4),
  ('A Team Meeting About a Delay', '{"prompt":"Why will the team miss the launch date?","options":["The marketing campaign was cancelled","The payment integration took longer and testing found issues","A key team member left","The customers asked for changes"],"correctIndex":1}', 2),
  ('A Team Meeting About a Delay', '{"prompt":"What is the speaker''s concern about launching without payments?","options":["Marketing would refuse","It would cost too much","Customers may hit a wall, leave and form a bad first impression","The second release would be late"],"correctIndex":2}', 3),
  ('A Team Meeting About a Delay', '{"prompt":"What does the speaker ask the team for before deciding?","options":["A list of customers'' complaints","Permission to cancel the launch","A new marketing plan","Their honest confidence in the ten-day estimate"],"correctIndex":3}', 4),
  ('A Museum Audio Guide', '{"prompt":"Why are visitors sometimes disappointed at first?","options":["The painting is damaged","The painting is smaller than they expect","The room is too dark","The painting is a copy"],"correctIndex":1}', 2),
  ('A Museum Audio Guide', '{"prompt":"What explains the special effect of the light in the painting?","options":["A special lamp was used","The wall was painted white","The paint was applied in very thin layers","It was painted near a real window"],"correctIndex":2}', 3),
  ('A Museum Audio Guide', '{"prompt":"What do art historians disagree about?","options":["The date of the painting","The price of the frame","Who painted the work","Whether the unfinished hands were deliberate"],"correctIndex":3}', 4),
  ('A Radio Essay on Silence', '{"prompt":"What happens to pauses in conversation, according to the speaker?","options":["They are usually respected","They are filled almost immediately","They make conversations more meaningful","They are rare in formal settings"],"correctIndex":1}', 2),
  ('A Radio Essay on Silence', '{"prompt":"What point does the speaker make about the quiet carriage on a train?","options":["It is a good place to think","It is the noisiest part of the train","It is quiet only in a narrow sense, as people listen through headphones","Nobody uses it"],"correctIndex":2}', 3),
  ('A Radio Essay on Silence', '{"prompt":"What does the speaker suggest may be the real reason we avoid silence?","options":["It is hard to find","It makes small sounds louder than they are","It is boring","It makes our own thoughts audible"],"correctIndex":3}', 4),
  ('A Debate on Learning Online', '{"prompt":"What does the speaker say was never the real bottleneck in education?","options":["Good teachers","Access to material","Student motivation","Funding for libraries"],"correctIndex":1}', 2),
  ('A Debate on Learning Online', '{"prompt":"What, according to the speaker, turns material into learning?","options":["Free access","Better technology","Structure such as deadlines, expert feedback and peers","Shorter courses"],"correctIndex":2}', 3),
  ('A Debate on Learning Online', '{"prompt":"How does the speaker reframe the question?","options":["Whether libraries are still needed","Whether universities should close","Whether online learning works at all","Whether we will fund the human parts of online learning"],"correctIndex":3}', 4)
) as gen(title_en, content, sort_order)
  on lc.title_en = gen.title_en;

insert into public.exercises (type, skill_area, listening_clip_id, cefr_level, content, sort_order)
select 'dictation'::exercise_type, 'listening'::skill_area, lc.id, lc.cefr_level, gen.content::jsonb, 1
from public.listening_clips lc
join (values
  ('A Voice Message from the Landlord', '{"audioText":"The building''s front door code is changing.","correctAnswer":"The building''s front door code is changing."}'),
  ('Booking a Doctor''s Appointment', '{"audioText":"I''ve had a sore throat for about a week.","correctAnswer":"I''ve had a sore throat for about a week."}'),
  ('Returning a Faulty Laptop', '{"audioText":"We can arrange a replacement in about five working days.","correctAnswer":"We can arrange a replacement in about five working days."}'),
  ('A Podcast Opening: Screens and Sleep', '{"audioText":"We''re not going to tell you to throw your phone away.","correctAnswer":"We''re not going to tell you to throw your phone away."}'),
  ('A Team Meeting About a Delay', '{"audioText":"First impressions are hard to undo.","correctAnswer":"First impressions are hard to undo."}'),
  ('A Museum Audio Guide', '{"audioText":"There''s no record that settles the question.","correctAnswer":"There''s no record that settles the question."}'),
  ('A Radio Essay on Silence', '{"audioText":"Silence isn''t empty at all.","correctAnswer":"Silence isn''t empty at all."}'),
  ('A Debate on Learning Online', '{"audioText":"Access to material was never really the bottleneck.","correctAnswer":"Access to material was never really the bottleneck."}')
) as gen(title_en, content)
  on lc.title_en = gen.title_en;

-- ============ Tidy existing content ============
update public.grammar_lessons set title_he = replace(title_he, ' — ', ': ') where title_he like '% — %';

update public.exercises set content = '{"prompt":"מה מתאר הדובר כשהוא אומר \"I''m kinda swamped\"?","options":["המון עבודה","רעב","בלבול","איחור"],"correctIndex":0}'::jsonb
where skill_area = 'listening' and content->>'prompt' = 'מה המשמעות של "I''m kinda swamped" בהקשר הזה?';

update public.exercises set content = '{"prompt":"איך הגיב מקום העבודה לאיחור, לפי מה שנאמר?","options":["הכעס היה גדול","אמרו שזה בסדר ואפשר להגיע כשמסתדר","ביקשו לא לבוא היום","לא ענו לטלפון"],"correctIndex":1}'::jsonb
where skill_area = 'listening' and content->>'prompt' = 'איך הגיב מקום העבודה למי שאיחר, לפי מה שנאמר?';

update public.exercises set content = jsonb_set(content, '{options,3}', '"זה זכור לי מצוין"'::jsonb)
where skill_area = 'listening' and content->>'prompt' = 'מה המשמעות של "I kinda forgot about that"?';
